from write_content import D,R,put,step,FILE,ZH,EN
import json

put('hnet-shapley-definition','Definition 1：经典 Shapley 定义','Definition 1: classical Shapley value',r'\varphi(i)=\sum_{T\subseteq N\setminus\{i\}}\frac{|T|!(|N|-|T|-1)!}{|N|!}\,[V(T\cup\{i\})-V(T)]',
'原定义使用中心化reward，保留阶乘权重与全部环境。','The original definition uses the centered reward, retaining its factorial weights and every environment.',[
step('hnet-shapley-def-domain','总体与分母',r'固定 $i\in N$，因而 $n=|N|\ge1$。每个 $T\subseteq N\setminus\{i\}$ 满足 $|T|\le n-1$，所有阶乘自变量非负，$n!$ 正。空环境也在和中；$n=1$ 时只有它。',en=('Check the universe and denominators',r'Fix $i\in N$, so $n=|N|\ge1$. Each environment satisfies $|T|\le n-1$, giving nonnegative factorial arguments and a positive factorial denominator. The empty environment is included and is the only environment in a one-player game.')),
step('hnet-shapley-def-center','中心化在边际中抵消',r'$V(T)=g(T)-b$，所以 $V(T\cup\{i\})-V(T)=g(T\cup\{i\})-g(T)$。因此定义没有改变原始游戏的Shapley值。归因不分配 $b$，效率的总值为 $g(N)-b$。',decl='Harsanyi.factorialShapley',en=('Cancel centering within each marginal',r'Subtracting the common output baseline cancels within every marginal. The definition therefore leaves classical Shapley unchanged from the raw game. It does not allocate the baseline; efficiency sums to $g(N)-b$.'))],scope='经典定义及其基线解释；无本地独立proof block。',en_scope='The classical definition and baseline interpretation; no independent local author proof block.',decls=['Harsanyi.factorialShapley'])
put('hnet-architecture','Eq.(5)–(8)：无偏置 Harsanyi block','Equations (5)–(8): the bias-free Harsanyi block',r'g_j(x)=\sum_{k\in C_j}A_{jk}z_k(x),\quad h_j(x)=g_j(x)\prod_{k\in C_j}\mathbf1_{z_k(x)\ne0},\quad z_j(x)=\max(h_j(x),0),\quad R_j=\bigcup_{k\in C_j}R_k',
'网络是有限前馈图；子节点可来自任意更早层，感受野按并集定义。','The network is a finite feed-forward graph; children may come from any earlier layer, and its field is their union.',[
step('hnet-arch-input','输入与选子矩阵',r'原输入 $z_i^{(0)}=x_i-r_i$，叶节点感受野为 $\{i\}$。$\Sigma_j$ 为二值对角矩阵，其1位置恰好是固定子节点集合 $C_j$，故矩阵乘法的线性式等于公式中的有限和。权重在推理期间固定，线性式不含bias。',en=('Input and child-selection matrix',r'The input is $z_i^{(0)}=x_i-r_i$, and the leaf field is a singleton. The ones of the binary diagonal matrix select exactly the fixed child set, so its matrix product equals the displayed finite sum. Inference weights are fixed and this operation has no bias.')),
step('hnet-arch-gate','AND gate 与 ReLU',r'所有子值非零时AND乘积为1，$h_j=g_j$；若某个子值为零，乘积为零且 $h_j=z_j=0$。即使gate为1，$g_j\le0$时ReLU仍可使输出为零。空子集的线性和为零、AND空积为1，因此输出仍为零。',decl='Harsanyi.Network.value',en=('AND gate and ReLU',r'The gate is one when all child values are nonzero and zero otherwise. A zero child therefore makes the block output zero. An open gate does not guarantee a nonzero output: a nonpositive linear value is still killed by ReLU. With no children, the linear sum is zero and the empty gate product is one, so the output remains zero.')),
step('hnet-arch-dag','共享节点与跳连的形式表示',r'有限前馈图按拓扑次序展开为有限树可重复引用相同子表达式；重复展开不改变每个节点的值。Lean Expr.block容许每个有限孩子为任意已构建子表达式，所以也包含跳连，且不假设各孩子的感受野互不相交。',decl='Harsanyi.Network.Expr',en=('Represent shared nodes and skip connections',r'A finite feed-forward graph can be unfolded in topological order into a finite expression tree, repeating shared subexpressions without changing their values. The finite-child block syntax admits any already built child expression, including skip connections, and does not assume disjoint child fields.'))],scope='原Eq.(5)–(8)的数学架构定义；不把训练STE或光滑gate视作已在同一定义中证明。',en_scope='The mathematical architecture of Equations (5)–(8); training STE and the separate smooth gate are not treated as already proved by this definition.',decls=['Harsanyi.Network.Expr','Harsanyi.Network.receptive','Harsanyi.Network.value'])
put('hnet-architecture-r1-r2','Theorem 4：架构推导 R1/R2','Theorem 4: derive R1/R2 from the architecture',r'\forall j,T,\quad z_j(x_T)=z_j(x)\mathbf1_{R_j\subseteq T}',
'按前馈拓扑顺序归纳，分别证明感受野依赖与缺变量沿一条祖先路径灭活。','Induct in feed-forward order to prove dependence on the receptive field and propagation of a missing variable along an ancestor path.',[
step('hnet-t4-r1-base','叶子与依赖归纳',r'叶 $i$ 的值是 $x_i-r_i$，只读取坐标 $i$。假设全部孩子已满足R1。若两输入在父场 $R_j$ 一致，则它们在每个孩子场一致，因子值由归纳假设全部相同。有限线性和、AND乘积和ReLU都是这些值的确定性函数，故父值相同。此归纳允许重叠场、共享孩子及跳连。',decl='Harsanyi.Network.value_congr',en=('Induct on the dependency field',r'A leaf reads only its own coordinate minus the baseline. If two inputs agree on a parent field, they agree on each child field. By induction all child values agree. The linear sum, gate and ReLU are deterministic functions of these values, so the parent values agree. Overlapping fields, shared children and skip connections remain allowed.')),
step('hnet-t4-r2-retained','感受野全部保留',r'当 $R_j\subseteq T$，掩码输入与原输入在该场相同，已证明的R1给 $z_j(x_T)=z_j(x)$，指示函数为1。空场也在这一情形内。',en=('Retain the entire field',r'If the field is contained in the retained mask, both samples agree on it and R1 gives identical unit values. The indicator is one; this case includes an empty field.')),
step('hnet-t4-r2-missing','缺变量的完整零值归纳',r'当 $R_j\not\subseteq T$，取 $i\in R_j\setminus T$。叶情形掩码给 $x_{T,i}=r_i$，所以值零。父情形由场的并集定义找一个孩子 $k$，使 $i\in R_k$；归纳假设给该孩子的掩码值零，AND乘积中这个因子为零，整个乘积为零，线性值无需计算，ReLU(0)=0。对每个父层重复同一论证即得到目标。这里只要求存在受影响孩子，不声称全部第一层节点都为零，也不把乘积等同其中一个因子。',decl='Harsanyi.Network.value_mask',en=('Prove the missing-variable case recursively',r'Choose a field variable omitted by the mask. A corresponding input leaf is zero because masking replaces its coordinate by the baseline. At a parent, the field union provides a child whose field contains that variable. Its masked value is zero by induction; one zero gate factor makes the entire product zero, and ReLU of zero is zero. Repeating this argument reaches the target. Only a relevant child must vanish: no claim that every first-layer neuron vanishes, or that an entire product equals one factor, is needed.')),
step('hnet-t4-baseline','独立证明空基线及空场',r'全部输入叶在基线处为零。父节点若有孩子则gate关；若无孩子则无偏置线性和为零。归纳得到每个单元基线值零。空感受野的R1表明其输出恒定，代入基线便知其恒零。因此实际架构中的空场边界成立，但不能把这一额外事实加入原Lemma1的R1/R2-only命题。',decl='Harsanyi.Network.value_baseline',en=('Prove the baseline and empty-field facts separately',r'All input leaves vanish at the baseline. A block with children has a closed gate there; one without children has a zero bias-free sum. Induction gives zero baseline value for every unit. An empty-field unit is constant by R1, so evaluating that constant at the baseline shows it is zero. This validates the architecture boundary without inserting the additional fact into the R1/R2-only lemma.'))],decls=['Harsanyi.Network.value_congr','Harsanyi.Network.value_mask','Harsanyi.Network.value_baseline','Harsanyi.Network.value_empty_receptive'])
put('hnet-smooth-gate','训练实现：STE 与光滑 AND','Training implementation: STE and a smooth AND',r'h_j(x)=g_j(x)\left[\prod_{k=1}^{M}\bigl(\Sigma_j\tanh(\gamma\Sigma_j z)+(I-\Sigma_j)\mathbf1\bigr)_k\right]^{1/\operatorname{tr}(\Sigma_j)}',
'这是训练实现的独立公式，不能因 hard-gate 定理通过而默认它全部参数域已证明。','This is a separate implementation formula; verification of the hard-gate theorem does not verify its entire parameter domain.',[
step('hnet-smooth-definition','精确记录原公式和梯度替代',r'原选子规则 $(\Sigma_j)_{ii}=\mathbf1_{(\tau_j)_i>0}$，前向仍用二值选子，反向采用 $\partial\Sigma_{ii}/\partial\tau_i=\beta e^{-\tau_i}/(1+e^{-\tau_i})^2$ 的STE替代。原光滑gate用所显示的几何平均形式，$\gamma>0$。这不是离散指示函数的真实导数，也不是Eq.(6)在全部非零孩子处取值1的严格相等式。',en=('Record the source formula and surrogate gradient',r'The forward child selection is the binary threshold of the trainable parameter. Backpropagation substitutes the displayed scaled logistic derivative as an STE. The separate smooth gate is a geometric mean of selected hyperbolic tangent values at positive scale. The surrogate is not the actual derivative of the discontinuous indicator, and the smooth gate is not identically one on all nonzero children.')),
step('hnet-smooth-boundary','分母和输入范围',r'若 $\operatorname{tr}\Sigma_j=0$，指数的分母为零，原文未给空children规则。非空选择并且孩子值非负时，tanh因子在[0,1)；若某孩子零，gate乘积零，能够复用“选子依赖、零孩子灭活”的数学机制。但第一层 $x-r$ 不经ReLU，原文“所有z前层都非负”没有自动覆盖该输入。本文不加非负或非空假设使这个训练公式变成原已证命题。',en=('Check denominator and input-domain boundaries',r'Zero selected children give a zero trace and an unspecified reciprocal exponent. With a nonempty selection and nonnegative children, the tangent factors lie in the stated interval and a zero child kills the product. This supports the same dependency and zero-child mechanism on that domain. The first-layer input, however, is the centered input before ReLU, so nonnegativity is not automatic there. No new nonnegative-input or nonempty-child premise is added to make the entire printed implementation formula a proved proposition.'))],status='complete',scope='完整训练定义与未声明边界说明；hard-gate的Lean通过不覆盖这个公式全部域。',en_scope='Complete implementation definition and its unspecified boundaries; hard-gate Lean verification does not cover this formula on its entire domain.')
put('hnet-runtime','未编号：归因累加的 O(nM) 运算计数','Unnumbered: O(nM) work for attribution accumulation',r'M=\sum_{l=1}^Lm^{(l)},\qquad \operatorname{cost}_{\mathrm{accumulate}}=O(nM)',
'前向输出已给定后，对每个变量与每个单元累加一个条件项。','Once all forward activations are available, accumulate one conditional term for each variable–unit pair.',[
step('hnet-runtime-count','有限索引对的数量',r'令 $n=|N|$、$M=|\mathcal J|$，变量/单元的笛卡尔积有 $nM$ 个元素。每个感受野及其基数可以在固定图上预处理，直接扫描这些对，测试成员并累加条件项，产生一个 O(nM) 算法。这个计数不要求输出非零，也不要求每个场都包含玩家。',en=('Count the finite index pairs',r'The player–unit Cartesian product has exactly $nM$ elements. With fields and cardinalities available from the fixed graph, scanning these pairs, testing membership and adding a conditional contribution provides the stated accumulation algorithm. This count does not require nonzero unit outputs or a field containing every player.')),
step('hnet-runtime-scope','“可忽略”的适用范围',r'正文还称这部分相对前向heavy cost可忽略，从而近似算一次前向。O(nM)本身没有证明此相对比较：它取决于架构、数据结构与硬件。这里保留原计算复杂度及其运算模型，不把比较句提升为一般渐近定理。',en=('Keep the comparative runtime claim in scope',r'The source also calls this cost negligible relative to a heavy forward pass and thus approximates the total as one pass. The pair count alone does not prove that relative comparison, which depends on architecture, data structures and hardware. The operation model is stated without turning the comparative sentence into a universal asymptotic theorem.'))],scope='归因算法的有限对计数及O(nM)上界；相对前向可忽略是未证明的比较描述。',en_scope='Finite pair counting and the O(nM) accumulation upper bound; negligibility relative to a forward pass is an unproved comparative description.')
put('hnet-sparsity-count','未编号：非零交互至多 M；经验截断边界','Unnumbered: at most M nonzero dividends; the empirical truncation boundary',r'\left|\{S\subseteq N:I(S)\ne0\}\right|\le M',
'非零交互只能出现在某个单元的感受野，重复场和抵消均不会增加数量。','A nonzero dividend must occur at some unit’s field; repeated fields and cancellation cannot increase the count.',[
step('hnet-count-support','证明支撑包含关系',r'Theorem2给加权单元交互和。由R1/R2的完整变换，单元的非零中心化交互只能位于它的非空场。若一个 $S$ 不等于任何单元的场，每项都为零，故模型交互也为零。因此非零交互集合包含于场的有限像集。',r'\{S:I(S)\ne0\}\subseteq\{R_j:j\in\mathcal J\}',decl='Harsanyi.Network.support_subset_fields',en=('Prove containment of the support',r'The weighted readout identity and the complete unit transform show that a unit can have a nonzero centered dividend only at its nonempty field. If a target equals no unit field, every summand vanishes. Therefore the nonzero-dividend family is contained in the finite image of the field map.')),
step('hnet-count-card','对像集取基数',r'有限包含给支撑基数不大于像集基数；有限像集基数不大于定义域 $\mathcal J$ 的基数 $M$。多个单元可以有同一场，且加权系数可相消，故只能给上界而非恰好M。',decl='Harsanyi.Network.support_card_le_units',en=('Bound the image cardinality',r'Finite containment bounds the support by the field image, whose cardinality is at most the number of units. Several units may share a field and their weighted effects may cancel, so the result is an upper bound rather than equality with M.')),
step('hnet-count-eq9','原 Eq.(9) 的中心化边界',r'原文 Eq.(9) 写 $v(x)=\sum_{S\in2^N}I(S)=\sum_{S\in\Omega}I(S)+\epsilon$，其中 $\epsilon=\sum_{S\notin\Omega}I(S)$。按原Definition2，和实际等于 $v(x)-v(x_\varnothing)$；讨论传统任意网络时若非零基线，第一等号错误，例如常数模型1所有中心化交互零。实际Harsanyi架构baseline=0可成立。截断式只定义tail，tail“小”是实验/外引主张，不由M上界证明。',en=('Check the centered boundary of source Equation (9)',r'Equation (9) prints the raw output as the sum of its centered dividends, then as retained dividends plus their omitted tail. Definition 2 makes that sum the output difference from the baseline. For a traditional network with a nonzero baseline the first equality is false: the constant-one model has zero centered dividends. The actual bias-free Harsanyi architecture has zero baseline, where it is valid. The tail expression defines a remainder; its being small is an empirical or cited claim, not a consequence of the M bound.'))],scope='M数量上界完整；原Eq9的原始输出等号在任意网络上错误，经验小tail不在形式化范围。',en_scope='The M upper bound is complete. The raw-output equality in Equation (9) is false for arbitrary networks, and empirical small-tail claims are outside the formal scope.',decls=['Harsanyi.Network.support_subset_fields','Harsanyi.Network.support_card_le_units'],original=r"""PDF page 6 states that HarsanyiNet learns at most $M=\sum_lm^{(l)}$ interactions, citing Lemma 1 and Theorem 2. It then prints Eq.(9): $v(x)=\sum_{S\in2^N}I(S)=\sum_{S\in\Omega}I(S)+\epsilon$, with $\epsilon=\sum_{S'\in2^N\setminus\Omega}I(S')$, claiming the omitted effects are negligible in typical experiments. There is no independent local proof block for the count or empirical small-tail claim.""")

FILE.write_text(json.dumps(D,ensure_ascii=False,indent=2)+'\n')
print('HarsanyiNet complete-or-classified rows',sum(r['rewrite_status']!='in_progress' for r in D['results']))
